BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·卷254·药元福传·赴灵州战事", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e66af1aafd18c0050199cc2962fef4065cc04d3a/content/books/zizhi-tongjian/vol-285/year-0946/part-03/sources/library/songshi-254-yao-lingzhou/source.txt", "note": "《宋史》卷254·药元福传·赴灵州战事，段落 songshi-9c6e46fee832-p057509；已核正文传主及上下文，底本原字保留，纸本及异文待核。", "id": "a34ad81e-1316-56b0-977f-4481156834d9"}, {"title": "资治通鉴·卷285·开运三年·八月至十月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e66af1aafd18c0050199cc2962fef4065cc04d3a/content/books/zizhi-tongjian/vol-285/year-0946/part-03/sources/library/tongjian-285-946-august-october/source.txt", "note": "《资治通鉴》卷285·开运三年·八月至十月及追述，段落 zizhi-tongjian-a63549944a71-p003387；已核正文传主及上下文，底本原字保留，纸本及异文待核。", "id": "28173612-f46c-5aee-bcff-992e0ccab0df"}, {"title": "资治通鉴·卷285·开运三年·陈觉返福州段同书校读", "source_type": "primary", "author": "司马光等", "edition": "维基文库固定修订2554328；API wikitext连续原字摘录，同书版本校读，纸本及版本字形待核。", "url": "https://github.com/greed-216/histree/blob/e66af1aafd18c0050199cc2962fef4065cc04d3a/content/books/zizhi-tongjian/vol-285/year-0946/part-03/sources/library/tongjian-285-946-chen-jue-collation/source.txt", "note": "《资治通鉴》卷285，维基文库固定修订2554328，wikitext字符4536—4831；用于陈觉陈诲人名校读，不算独立书证。", "id": "9c869bc4-561b-568b-aa78-9dd9fc0ece75"}, {"title": "资治通鉴·卷285·开运三年·七月至八月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/tongjian-285-946-july-august/source.txt", "note": "《资治通鉴》卷285·开运三年·七月至八月及追述，段落 zizhi-tongjian-a63549944a71-p003386；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "9065cf5f-3381-582d-95c8-f62f9e013675"}, {"title": "旧五代史·卷84·晋少帝本纪·开运三年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-084-946-august/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年八月，段落 jiu-wudaishi-205deb4a7860-p002041；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "dbf98f5f-500c-5272-94f5-172e997dd77e"}, {"title": "旧五代史·卷84·晋少帝本纪·开运三年九月及赵延寿书信追述", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-084-946-zhao-correspondence/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年九月及赵延寿书信追述，段落 jiu-wudaishi-205deb4a7860-p002042；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "c4802c9d-998b-5954-a3e2-b9d3cdf08d38"}, {"title": "旧五代史·卷99·汉高祖本纪·开运年间及白承福之死", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-099-bai-chengfu-death/source.txt", "note": "《旧五代史》卷99·汉高祖本纪·开运年间及白承福之死，段落 jiu-wudaishi-205deb4a7860-p002425；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "bf9fe11b-db0c-51fd-bf1f-6910977a4ee3"}, {"title": "新五代史·卷62·南唐世家·陈觉赴福州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/xinwudaishi-062-chen-jue-fuzhou/source.txt", "note": "《新五代史》卷62·南唐世家·陈觉赴福州，段落 xin-wudaishi-b08f244b9241-p003142；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "cef07fa0-ebe4-551b-8758-4a3b3e4794b6"}, {"title": "新五代史·卷65·南汉世家·刘晟乾和三年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/xinwudaishi-065-hongya-death/source.txt", "note": "《新五代史》卷65·南汉世家·刘晟乾和三年，段落 xin-wudaishi-b08f244b9241-p003283；已核卷号与传主，电子本及异文待纸本校核。", "id": "6d196b4f-4d62-5838-ad21-786fb0df513d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "顾忠", "aliases": ["顧忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐侍卫官。946年八月条下记陈觉伪造诏令，派他召李仁达入朝。原TXT段首误写陈诲，已结合本段上下文、《新五代史》和另一《通鉴》版本校读为陈觉。顾忠生卒、籍贯未载。", "biography": null, "status": "draft", "id": "230c99e6-68ab-564d-9296-e000faedc3fa"}, {"name": "李仁达", "aliases": ["李仁達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "杨崇保", "aliases": ["楊崇保"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州楼船指挥使。946年陈觉、冯延鲁攻福州时，李仁达派他领州兵抵抗；八月丁丑在候官被陈觉、冯延鲁击败。生卒年未载。", "biography": null, "status": "draft", "id": "bf5ef64c-f5e7-5fcb-808f-af71f52654eb"}, {"name": "陈诲", "aliases": ["陳誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建安人，王延政麾下战棹都头。940年三月在夜袭中杀死潘师逵。生卒年未载。", "biography": null, "status": "draft", "id": "8c18058e-c4f8-52ab-a4d2-9caaba34336a"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "杨匡邺", "aliases": ["杨匡鄴", "楊匡鄴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐左神威指挥使。946年八月戊寅，陈觉、冯延鲁乘胜进攻福州西关，遭李仁达出击大败，杨匡邺被俘。后续命运及生卒年未载。", "biography": null, "status": "draft", "id": "38206378-e95c-5716-ad8c-bf8c9578d70c"}, {"name": "王崇文", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐百胜军节度使。945年建州陷落后受任永安节度使，《资治通鉴》记他治理宽简，建州百姓渐安。生卒年本段未载。", "biography": null, "status": "draft", "id": "e00c8607-6426-5398-b911-e9eba22c7740"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "拓跋彦超", "aliases": ["拓跋彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "党项首领。939年冯晖接任朔方节度使后，拓跋彦超前往祝贺，受到优待并被留在城中。生卒年未载。", "biography": null, "status": "draft", "id": "07cc4da4-56f5-51e9-b06f-b2b7fe597419"}, {"name": "药元福", "aliases": ["藥元福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州晋阳人，早年侍奉王檀及后唐，曾任深州刺史。945年任后晋马军右厢副排阵使，在白团卫村被围时主张逆风急击，与符彦卿、张彦泽、皇甫遇领骑兵出战。《宋史》还记他战后任威州刺史。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "9bbd6971-3005-5379-8428-512e90ae87d6"}, {"name": "陈道庠", "aliases": ["陳道庠", "陈道痒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉指挥使，端州人。942年钱帛馆之战中救出被围的刘弘昌、刘弘杲。主书前处写陈道痒，同段籍贯句及新五代史写陈道庠，姓名据此校读，原文不改。", "biography": null, "status": "draft", "id": "8c0e66da-c540-5719-8bf2-606db592f4bf"}, {"name": "邓伸", "aliases": ["鄧伸"], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "南汉特进，陈道庠的朋友。刘思潮等死后，他送陈道庠《汉纪》，以韩信、彭越的遭遇提醒其危险。刘晟闻知后，邓伸与陈道庠均被杀并夷族；《资治通鉴》列在946年九月，《新五代史》补记下狱、斩于市。出生年未载。", "biography": null, "status": "draft", "id": "571d3a45-76cf-512f-bb99-5be67d65b18e"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "马捷", "aliases": ["馬捷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州排阵使。946年九月辛丑，他引南唐兵从马牧山攻入福州，抵善化门桥。底本官职写排陈使，展示采用排阵使；生卒年未载。", "biography": null, "status": "draft", "id": "0c14a705-9a81-5af3-a7a2-fce636e0eea7"}, {"name": "丁彦贞", "aliases": ["丁彥貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州都指挥使。946年九月辛丑，马捷引南唐军攻入后，他率一百人于善化门桥抵抗；李仁达随后退保善化门。生卒年未载。", "biography": null, "status": "draft", "id": "e8b6d725-01a0-511b-81d1-ab5573c5f54e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

