SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "慕容彦超违法征敛，取官麦五百斛制酒曲并摊派给百姓。", "citation": "卷285·后晋开运三年（946年八月至九月及追述）·zztj-v285-y0946-p017·原文件第47行", "note": "原文：濮州刺史慕容彦超坐违法科敛，擅取官麦五百斛造麹，赋与部民。；核对说明：造麹为制作酒曲，赋与部民为摊派；不猜价格和每户数量。", "status": "draft", "id": "6f528636-c424-5583-8765-2bc448fee886", "subject_id": "a9f711b1-8f42-5d21-b3df-ce48007dc7e6", "source_id": "9065cf5f-3381-582d-95c8-f62f9e013675"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "946年八月受处分以前，违法行为具体日未载", "citation": "卷285·后晋开运三年（946年八月至九月及追述）·zztj-v285-y0946-p017·原文件第47行", "note": "原文：濮州刺史慕容彦超坐违法科敛，擅取官麦五百斛造麹，赋与部民。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "96dc5702-b9c6-5c37-9ed2-f047e8a965b6", "subject_id": "a9f711b1-8f42-5d21-b3df-ce48007dc7e6", "source_id": "9065cf5f-3381-582d-95c8-f62f9e013675"}, {"subject_table": "person", "field_path": "description", "claim_text": "慕容彦超：擅取官麦制曲，摊派给百姓。", "citation": "卷285·后晋开运三年（946年八月至九月及追述）·zztj-v285-y0946-p017·原文件第47行", "note": "原文：濮州刺史慕容彦超坐违法科敛，擅取官麦五百斛造麹，赋与部民。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "4d85e923-febc-58f0-ac78-4f9d1831c1f7", "subject_id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b", "source_id": "9065cf5f-3381-582d-95c8-f62f9e013675"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "慕容彦超：擅取官麦制曲，摊派给百姓。", "citation": "卷285·后晋开运三年（946年八月至九月及追述）·zztj-v285-y0946-p017·原文件第47行", "note": "原文：濮州刺史慕容彦超坐违法科敛，擅取官麦五百斛造麹，赋与部民。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f0304255-a984-5286-89b8-cea315e3298a", "subject_id": "d8b575d3-7827-591e-b405-fab6d4d17a89", "source_id": "9065cf5f-3381-582d-95c8-f62f9e013675"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记慕容彦超此时为棣州刺史，因前任濮州时擅取省仓麦、私卖官面而应处死。", "citation": "《旧五代史》卷84·晋少帝本纪·开运三年八月，段落 jiu-wudaishi-205deb4a7860-